// Public links (ADR-026): read-only VIEW links and PRESENTER links that open a deck without an account.
//
// Rules this module enforces (the HTTP layer adds sessions, CSRF, rate limits and the instance switches):
// - only the human owner creates, lists, changes or turns off links (agents never: FORBIDDEN_ACTOR); an agent may
//   learn how many links are active, never their secrets, labels or ids (`countShareLinks`);
// - the secret is generated by the `ShareLinkSecrets` port (128 CSPRNG bits), stored only as a keyed lookup hash and
//   a sealed (encrypted) copy, and returned only to the owner;
// - resolving a secret is one hash + one indexed lookup + a constant-time compare, and every failure (unknown,
//   revoked, expired, trashed deck, missing pinned revision) is the same `null`;
// - limits: 50 active links per deck and 500 per workspace; labels are plain text of at most 80 characters with
//   control, bidi and invisible characters removed; expiry within a year;
// - audit entries name the link id (`share:<id>`) and never carry the secret or the label.
import { limitExceeded, notFound, presentationNotFound, validationError } from "../errors.js";
import type {
  DeckRecord,
  Repositories,
  ShareLinkKind,
  ShareLinkPatch,
  ShareLinkRecord,
  ShareLinkSecrets,
} from "../ports.js";
import { type CallContext, type Principal, requireOwner, requireScope } from "../principal.js";
import {
  audit,
  type Ctx,
  loadLiveDeck,
  requireObject,
  requireString,
  runRead,
  runWrite,
} from "./context.js";

export const SHARE_LINK_LIMITS = {
  /** Active (not revoked, not expired) links per deck. */
  perDeck: 50,
  /** Active links per workspace (instance). */
  perWorkspace: 500,
  /** Characters of the owner's private label. */
  labelChars: 80,
  /** Farthest expiry the owner can choose. */
  maxExpiryMs: 366 * 24 * 60 * 60 * 1000,
  /** Closest expiry (a link that is dead on arrival is a mistake). */
  minExpiryMs: 60 * 1000,
} as const;

export const SHARE_LINK_KINDS: readonly ShareLinkKind[] = ["view", "presenter"];
const SECRET = /^[A-Za-z0-9_-]{22}$/;
/** Hashed instead of an invalid secret, so a malformed URL costs the same work as a well-formed one. */
const DECOY_SECRET = "AAAAAAAAAAAAAAAAAAAAAA";

/** What the owner sees of a link. `secret` is `null` when the sealed copy cannot be opened (rotated instance key). */
export interface ShareLinkView {
  id: string;
  presentationId: string;
  kind: ShareLinkKind;
  label: string;
  createdAt: number;
  expiresAt: number | null;
  pinnedRevision: number | null;
  lastOpenedAt: number | null;
  openCount: number;
  /** `active`, or `expired` (kept in the list so the owner can extend it). Revoked links are never listed. */
  state: "active" | "expired";
  secret: string | null;
}

export interface CreateShareLinkInput {
  presentationId: string;
  kind: ShareLinkKind;
  label?: string;
  /** Epoch ms, or `null`/absent: never expires. */
  expiresAt?: number | null;
  /** `true`: freeze the link on the current revision. */
  pinRevision?: boolean;
}

export interface UpdateShareLinkInput {
  presentationId: string;
  linkId: string;
  label?: string;
  expiresAt?: number | null;
  /** `"current"`: freeze on the current revision; a number: that revision; `null`: follow the latest again. */
  pinnedRevision?: number | "current" | null;
}

/** A link a guest may use right now, with the deck and the revision it shows. */
export interface ResolvedShareLink {
  link: ShareLinkRecord;
  deck: DeckRecord;
  /** The revision to serve: the pinned one, or the deck's current revision. */
  revision: number;
}

/**
 * Removes control, bidi and invisible characters, collapses whitespace, trims and caps a label. Plain text only:
 * the panel shows it with text interpolation.
 */
export function cleanShareLabel(value: unknown): string {
  if (value === undefined || value === null) return "";
  if (typeof value !== "string") {
    throw validationError("label must be a string", { path: "label" });
  }
  const text = value
    .slice(0, SHARE_LINK_LIMITS.labelChars * 4)
    .replace(/[\ud800-\udbff](?![\udc00-\udfff])|(?<![\ud800-\udbff])[\udc00-\udfff]/g, "")
    .replace(/[­؜᠎​-‏‪-‮⁠-⁩﻿￹-￻]/g, "")
    .replace(/[\u0000-\u001f\u007f-\u009f]/g, " ")
    .replace(/\s+/g, " ")
    .trim();
  if (text.length > SHARE_LINK_LIMITS.labelChars) {
    throw validationError(`label must be at most ${SHARE_LINK_LIMITS.labelChars} characters`, {
      path: "label",
      hint: "Use a short name, such as who the link is for.",
    });
  }
  return text;
}

function requireKind(value: unknown): ShareLinkKind {
  if (value !== "view" && value !== "presenter") {
    throw validationError('kind must be "view" or "presenter"', { path: "kind" });
  }
  return value;
}

function checkExpiry(value: unknown, now: number): number | null {
  if (value === undefined || value === null) return null;
  if (!Number.isSafeInteger(value)) {
    throw validationError("expiresAt must be a time (epoch milliseconds) or null", {
      path: "expiresAt",
    });
  }
  const at = value as number;
  if (at < now + SHARE_LINK_LIMITS.minExpiryMs) {
    throw validationError("The expiry must be in the future", {
      path: "expiresAt",
      hint: "Pick a later date, or no expiry.",
    });
  }
  if (at > now + SHARE_LINK_LIMITS.maxExpiryMs) {
    throw validationError("The expiry must be within a year", {
      path: "expiresAt",
      hint: "Pick a date within the next 12 months, or no expiry.",
    });
  }
  return at;
}

function isActive(link: ShareLinkRecord, now: number): boolean {
  return link.revokedAt === null && (link.expiresAt === null || link.expiresAt > now);
}

function secretsOf(ctx: Ctx): ShareLinkSecrets {
  if (ctx.shareSecrets === undefined) {
    throw validationError("Public links are not available on this server", {
      hint: "The server was started without public-link support.",
    });
  }
  return ctx.shareSecrets;
}

function viewOf(ctx: Ctx, link: ShareLinkRecord, now: number): ShareLinkView {
  let secret: string | null = null;
  try {
    secret = ctx.shareSecrets?.open(link.sealedSecret, link.id) ?? null;
  } catch {
    secret = null;
  }
  return {
    id: link.id,
    presentationId: link.deckId,
    kind: link.kind,
    label: link.label,
    createdAt: link.createdAt,
    expiresAt: link.expiresAt,
    pinnedRevision: link.pinnedRevision,
    lastOpenedAt: link.lastOpenedAt,
    openCount: link.openCount,
    state: isActive(link, now) ? "active" : "expired",
    secret,
  };
}

/** The live link `linkId` of the deck, or NOT_FOUND (also for a revoked link: it is gone for the owner). */
async function loadLink(
  repos: Repositories,
  principal: Principal,
  deckId: string,
  linkId: string,
): Promise<ShareLinkRecord> {
  const link = await repos.shareLinks.get(principal.workspaceId, linkId);
  if (link === null || link.deckId !== deckId || link.revokedAt !== null) {
    throw notFound(`Link "${linkId.slice(0, 40)}" does not exist`, {
      path: "linkId",
      hint: "List the presentation's links to get valid ids.",
    });
  }
  return link;
}

async function checkPin(
  repos: Repositories,
  principal: Principal,
  deck: DeckRecord,
  value: unknown,
): Promise<number | null> {
  if (value === null) return null;
  if (value === "current") return deck.currentRevision;
  if (!Number.isSafeInteger(value) || (value as number) < 1) {
    throw validationError('pinnedRevision must be a revision number, "current" or null', {
      path: "pinnedRevision",
    });
  }
  const revision = await repos.revisions.get(principal.workspaceId, deck.id, value as number);
  if (revision === null) {
    throw validationError(`Revision ${value as number} does not exist`, {
      path: "pinnedRevision",
      hint: "Pin the current revision, or follow the latest one.",
    });
  }
  return value as number;
}

/** Human owner only (a human hands out links; agents never do, ADR-026). */
function requireLinkOwner(principal: Principal, action: string): void {
  requireScope(principal, "decks:read");
  requireOwner(principal, action);
}

const linkTarget = (input: unknown): string | null => {
  const id = (input as { presentationId?: unknown } | null)?.presentationId;
  return typeof id === "string" && id.length <= 64 ? `deck:${id}` : null;
};

export async function createShareLink(
  ctx: Ctx,
  principal: Principal,
  rawInput: CreateShareLinkInput,
  call?: CallContext,
): Promise<ShareLinkView> {
  return runWrite(ctx, principal, call, "share_link.create", linkTarget(rawInput), async () => {
    requireLinkOwner(principal, "create a public link");
    const input = requireObject(rawInput);
    const deckId = requireString(input.presentationId, "presentationId");
    const kind = requireKind(input.kind);
    const label = cleanShareLabel(input.label);
    const now = ctx.clock.now();
    const expiresAt = checkExpiry(input.expiresAt, now);
    if (input.pinRevision !== undefined && typeof input.pinRevision !== "boolean") {
      throw validationError("pinRevision must be true or false", { path: "pinRevision" });
    }
    const secrets = secretsOf(ctx);
    const ws = principal.workspaceId;
    return ctx.store.transaction(async (tx) => {
      const deck = await loadLiveDeck(tx, principal, deckId);
      const perDeck = await tx.shareLinks.countActive(ws, now, deckId);
      if (perDeck >= SHARE_LINK_LIMITS.perDeck) {
        throw limitExceeded(
          "Active links of this presentation",
          SHARE_LINK_LIMITS.perDeck,
          perDeck + 1,
          {
            hint: "Turn off links you no longer need, then try again.",
          },
        );
      }
      const total = await tx.shareLinks.countActive(ws, now);
      if (total >= SHARE_LINK_LIMITS.perWorkspace) {
        throw limitExceeded(
          "Active links on this server",
          SHARE_LINK_LIMITS.perWorkspace,
          total + 1,
          {
            hint: "Turn off links you no longer need, then try again.",
          },
        );
      }
      const id = ctx.ids.ulid();
      const secret = secrets.generate();
      if (!SECRET.test(secret)) throw new Error("bad share secret format");
      const link: ShareLinkRecord = {
        workspaceId: ws,
        id,
        deckId,
        kind,
        label,
        secretHash: secrets.hash(secret),
        sealedSecret: secrets.seal(secret, id),
        createdAt: now,
        expiresAt,
        pinnedRevision: input.pinRevision === true ? deck.currentRevision : null,
        revokedAt: null,
        revokedReason: null,
        lastOpenedAt: null,
        openCount: 0,
      };
      await tx.shareLinks.insert(link);
      await audit(ctx, tx, principal, call, "share_link.create", `share:${id}`, "ok", {
        deck: deckId,
        kind,
        expiresAt,
        pinnedRevision: link.pinnedRevision,
      });
      return { ...viewOf(ctx, link, now), secret };
    });
  });
}

/** Human owner only. The deck's links that are not turned off (active and expired), newest first. */
export async function listShareLinks(
  ctx: Ctx,
  principal: Principal,
  rawInput: { presentationId: string },
  call?: CallContext,
): Promise<ShareLinkView[]> {
  return runRead(call, async () => {
    requireLinkOwner(principal, "see public links");
    const deckId = requireString(requireObject(rawInput).presentationId, "presentationId");
    await loadLiveDeck(ctx.store, principal, deckId);
    const now = ctx.clock.now();
    const links = await ctx.store.shareLinks.listForDeck(principal.workspaceId, deckId);
    return links.filter((l) => l.revokedAt === null).map((l) => viewOf(ctx, l, now));
  });
}

/** Human owner only. Rename, change the expiry (an expired link can be extended), freeze or unfreeze. */
export async function updateShareLink(
  ctx: Ctx,
  principal: Principal,
  rawInput: UpdateShareLinkInput,
  call?: CallContext,
): Promise<ShareLinkView> {
  return runWrite(ctx, principal, call, "share_link.update", linkTarget(rawInput), async () => {
    requireLinkOwner(principal, "change a public link");
    const input = requireObject(rawInput);
    const deckId = requireString(input.presentationId, "presentationId");
    const linkId = requireString(input.linkId, "linkId", 64);
    const now = ctx.clock.now();
    const patch: ShareLinkPatch = {};
    if (input.label !== undefined) patch.label = cleanShareLabel(input.label);
    if (input.expiresAt !== undefined) patch.expiresAt = checkExpiry(input.expiresAt, now);
    const ws = principal.workspaceId;
    return ctx.store.transaction(async (tx) => {
      const deck = await loadLiveDeck(tx, principal, deckId);
      const link = await loadLink(tx, principal, deckId, linkId);
      if (input.pinnedRevision !== undefined) {
        patch.pinnedRevision = await checkPin(tx, principal, deck, input.pinnedRevision);
      }
      // Extending an expired link brings it back: it counts against the limits again.
      if (!isActive(link, now) && isActive({ ...link, ...patch }, now)) {
        const perDeck = await tx.shareLinks.countActive(ws, now, deckId);
        if (perDeck >= SHARE_LINK_LIMITS.perDeck) {
          throw limitExceeded(
            "Active links of this presentation",
            SHARE_LINK_LIMITS.perDeck,
            perDeck + 1,
          );
        }
        const total = await tx.shareLinks.countActive(ws, now);
        if (total >= SHARE_LINK_LIMITS.perWorkspace) {
          throw limitExceeded(
            "Active links on this server",
            SHARE_LINK_LIMITS.perWorkspace,
            total + 1,
          );
        }
      }
      await tx.shareLinks.update(ws, deckId, linkId, patch);
      await audit(ctx, tx, principal, call, "share_link.update", `share:${linkId}`, "ok", {
        deck: deckId,
        ...(patch.label === undefined ? {} : { label: "changed" }),
        ...(patch.expiresAt === undefined ? {} : { expiresAt: patch.expiresAt }),
        ...(patch.pinnedRevision === undefined ? {} : { pinnedRevision: patch.pinnedRevision }),
      });
      return viewOf(ctx, { ...link, ...patch }, now);
    });
  });
}

/** Human owner only. Turns one link off for good (a new link is a new secret). */
export async function revokeShareLink(
  ctx: Ctx,
  principal: Principal,
  rawInput: { presentationId: string; linkId: string },
  call?: CallContext,
): Promise<{ revoked: true }> {
  return runWrite(ctx, principal, call, "share_link.revoke", linkTarget(rawInput), async () => {
    requireLinkOwner(principal, "turn off a public link");
    const input = requireObject(rawInput);
    const deckId = requireString(input.presentationId, "presentationId");
    const linkId = requireString(input.linkId, "linkId", 64);
    return ctx.store.transaction(async (tx) => {
      await loadLiveDeck(tx, principal, deckId);
      await loadLink(tx, principal, deckId, linkId);
      await tx.shareLinks.update(principal.workspaceId, deckId, linkId, {
        revokedAt: ctx.clock.now(),
        revokedReason: "owner",
      });
      await audit(ctx, tx, principal, call, "share_link.revoke", `share:${linkId}`, "ok", {
        deck: deckId,
      });
      return { revoked: true as const };
    });
  });
}

/** Human owner only. Turns off every link of the deck. */
export async function revokeAllShareLinks(
  ctx: Ctx,
  principal: Principal,
  rawInput: { presentationId: string },
  call?: CallContext,
): Promise<{ revoked: number }> {
  return runWrite(ctx, principal, call, "share_link.revoke_all", linkTarget(rawInput), async () => {
    requireLinkOwner(principal, "turn off public links");
    const deckId = requireString(requireObject(rawInput).presentationId, "presentationId");
    return ctx.store.transaction(async (tx) => {
      await loadLiveDeck(tx, principal, deckId);
      const revoked = await tx.shareLinks.revokeAllForDeck(
        principal.workspaceId,
        deckId,
        ctx.clock.now(),
        "owner",
      );
      await audit(ctx, tx, principal, call, "share_link.revoke_all", `deck:${deckId}`, "ok", {
        revoked,
      });
      return { revoked };
    });
  });
}

/**
 * `decks:read` (agents included). How many links of the deck are active, and how many the trash turned off. Counts
 * only: never a secret, an id or a label.
 */
export async function countShareLinks(
  ctx: Ctx,
  principal: Principal,
  rawInput: { presentationId: string },
  call?: CallContext,
): Promise<{ active: number; turnedOffByTrash: number }> {
  return runRead(call, async () => {
    requireScope(principal, "decks:read");
    const deckId = requireString(requireObject(rawInput).presentationId, "presentationId");
    const deck = await ctx.store.decks.get(principal.workspaceId, deckId);
    // The trash is the owner's: agents see a trashed deck as missing.
    if (deck === null || (deck.deletedAt !== null && principal.actor !== "owner")) {
      throw presentationNotFound(deckId);
    }
    const now = ctx.clock.now();
    if (deck.deletedAt !== null) {
      // A deck in the trash: its links are off; say how many the owner could turn back on.
      const links = await ctx.store.shareLinks.listForDeck(principal.workspaceId, deckId);
      return {
        active: 0,
        turnedOffByTrash: links.filter(
          (l) => l.revokedReason === "trash" && (l.expiresAt === null || l.expiresAt > now),
        ).length,
      };
    }
    return {
      active: await ctx.store.shareLinks.countActive(principal.workspaceId, now, deckId),
      turnedOffByTrash: 0,
    };
  });
}

/**
 * Guest side, no principal: the link a secret opens right now, or `null` for ANY failure (malformed, unknown,
 * turned off, expired, deck in the trash or gone, pinned revision missing). Always hashes once and looks up once,
 * so a malformed secret costs about the same as a wrong one.
 */
export async function resolveShareLink(
  ctx: Ctx,
  workspaceId: string,
  secret: unknown,
): Promise<ResolvedShareLink | null> {
  const secrets = ctx.shareSecrets;
  if (secrets === undefined) return null;
  const wellFormed = typeof secret === "string" && SECRET.test(secret);
  const hash = secrets.hash(wellFormed ? (secret as string) : DECOY_SECRET);
  const link = await ctx.store.shareLinks.findByHash(workspaceId, hash);
  if (!wellFormed || link === null || !secrets.matches(link.secretHash, hash)) return null;
  return checkLinkState(ctx, link);
}

/** Guest side, on every later request: the link `linkId` of `deckId` still works (same rules as resolving). */
export async function checkShareLink(
  ctx: Ctx,
  workspaceId: string,
  linkId: string,
  deckId: string,
): Promise<ResolvedShareLink | null> {
  const link = await ctx.store.shareLinks.get(workspaceId, linkId);
  if (link === null || link.deckId !== deckId) return null;
  return checkLinkState(ctx, link);
}

async function checkLinkState(ctx: Ctx, link: ShareLinkRecord): Promise<ResolvedShareLink | null> {
  if (!isActive(link, ctx.clock.now())) return null;
  const deck = await ctx.store.decks.get(link.workspaceId, link.deckId);
  if (deck === null || deck.deletedAt !== null) return null;
  const revision = link.pinnedRevision ?? deck.currentRevision;
  if (link.pinnedRevision !== null) {
    const exists = await ctx.store.revisions.get(link.workspaceId, link.deckId, revision);
    if (exists === null) return null;
  }
  return { link, deck, revision };
}

/** Guest side: counts one opening of a working link (the guest page calls it once per load). */
export async function recordShareLinkOpen(
  ctx: Ctx,
  workspaceId: string,
  linkId: string,
): Promise<void> {
  await ctx.store.shareLinks.recordOpen(workspaceId, linkId, ctx.clock.now());
}
